[Description("Search the web for information on a query. Returns search result snippets with titles and URLs.")]
static async Task<string> WebSearch(
    [Description("The search query string")] string query)
{
    Console.WriteLine($"  🌐 Searching: \"{query}\"");

    using var http = new HttpClient();
    http.DefaultRequestHeaders.UserAgent.ParseAdd(
        "ResearchAgent/1.0 (compatible; research-bot)");

    try
    {
        // Use DuckDuckGo Instant Answer API (no key required)
        var encoded = Uri.EscapeDataString(query);
        var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
        var json = await http.GetStringAsync(url);

        using var doc = System.Text.Json.JsonDocument.Parse(json);
        var root = doc.RootElement;

        var results = new System.Text.StringBuilder();

        // Abstract
        var abstractText = root.GetProperty("AbstractText").GetString();
        var abstractUrl = root.GetProperty("AbstractURL").GetString();
        if (!string.IsNullOrWhiteSpace(abstractText))
        {
            results.AppendLine($"## Summary\n{abstractText}\nSource: {abstractUrl}\n");
        }

        // Related topics
        if (root.TryGetProperty("RelatedTopics", out var topics))
        {
            var count = 0;
            foreach (var item in topics.EnumerateArray())
            {
                if (count >= 8) break;
                var text = item.TryGetProperty("Text", out var t) ? t.GetString() : null;
                var link = item.TryGetProperty("FirstURL", out var u) ? u.GetString() : null;
                if (!string.IsNullOrWhiteSpace(text))
                {
                    results.AppendLine($"- {text}");
                    if (!string.IsNullOrWhiteSpace(link))
                        results.AppendLine($"  URL: {link}");
                    count++;
                }
            }
        }

        var output = results.ToString();
        return string.IsNullOrWhiteSpace(output)
            ? $"No detailed results found for \"{query}\". Try rephrasing the query."
            : output;
    }
    catch (Exception ex)
    {
        return $"Search failed: {ex.Message}. Try a different query.";
    }
}

[Description("Save a research note with a title and content for later reference.")]
string SaveNote(
    [Description("Short descriptive title for the note")] string title,
    [Description("The note content with key facts and source URLs")] string content)
{
    notebook.Add((title, content));
    Console.WriteLine($"  📝 Note saved: \"{title}\"");
    return $"Note #{notebook.Count} saved: \"{title}\"";
}

[Description("Retrieve all saved research notes to review before writing the summary.")]
string GetNotes()
{
    if (notebook.Count == 0)
        return "No notes saved yet.";

    Console.WriteLine($"  📋 Reviewing {notebook.Count} note(s)");
    var sb = new System.Text.StringBuilder();
    for (var i = 0; i < notebook.Count; i++)
    {
        var (title, content) = notebook[i];
        sb.AppendLine($"### Note #{i + 1}: {title}");
        sb.AppendLine(content);
        sb.AppendLine();
    }
    return sb.ToString();
